//! Bounded two-slot protected payloads. Caller serializes writers and owns
//! lifecycle/tombstone checks; this primitive never restores authority.
use crate::{secrets::{CredentialStore,ServiceProfile,SecretBlob},startup_local::Scope};
use serde::{Serialize,Deserialize};use sha2::{Digest,Sha256};use zeroize::Zeroizing;
const CHUNK:usize=2048;const MAX:usize=73728;
#[derive(Serialize,Deserialize)]#[serde(deny_unknown_fields)]struct Head{slot:u8,len:usize,digest:String}
fn key(s:&Scope,purpose:&str,world:uuid::Uuid,part:&str)->Result<ServiceProfile,String>{let bytes=serde_json::to_vec(&(purpose,&s.account,s.device,world,part)).map_err(|_|"Protected key encoding")?;let h=Sha256::digest(bytes);ServiceProfile::new(&s.origin,&s.service,uuid::Uuid::from_bytes(h[..16].try_into().unwrap())).map_err(|_|"Protected issuer scope".into())}
pub fn save<S:CredentialStore>(store:&S,s:&Scope,purpose:&str,world:uuid::Uuid,bytes:&[u8])->Result<(),String>{if bytes.is_empty()||bytes.len()>MAX{return Err("Protected payload bound".into())}let head=key(s,purpose,world,"head")?;let old=store.load(&head).map_err(|e|format!("Protected commit read: {e}"))?;let slot=if let Some(b)=old{let h:Head=serde_json::from_slice(b.bytes()).map_err(|_|"Protected commit corrupt")?;if h.slot>1{return Err("Protected slot bound".into())}1-h.slot}else{0};for(n,part)in bytes.chunks(CHUNK).enumerate(){store.save(&key(s,purpose,world,&format!("{slot}:{n}"))?,&SecretBlob::new(part.to_vec()).map_err(|_|"Protected chunk bound")?).map_err(|e|format!("Protected chunk write: {e}"))?}let h=Head{slot,len:bytes.len(),digest:format!("{:x}",Sha256::digest(bytes))};store.save(&head,&SecretBlob::new(serde_json::to_vec(&h).map_err(|_|"Protected commit encoding")?).map_err(|_|"Protected commit bound")?).map_err(|e|format!("Protected commit write: {e}; payload_bytes={}; chunks={}",bytes.len(),bytes.len().div_ceil(CHUNK)))}
pub fn load<S:CredentialStore>(store:&S,s:&Scope,purpose:&str,world:uuid::Uuid)->Result<Option<Zeroizing<Vec<u8>>>,String>{let Some(b)=store.load(&key(s,purpose,world,"head")?).map_err(|e|format!("Protected commit read: {e}"))?else{return Ok(None)};let h:Head=serde_json::from_slice(b.bytes()).map_err(|_|"Protected commit corrupt")?;if h.slot>1||h.len==0||h.len>MAX||h.digest.len()!=64{return Err("Protected commit bound".into())}let mut bytes=Zeroizing::new(Vec::with_capacity(h.len));for n in 0..h.len.div_ceil(CHUNK){let b=store.load(&key(s,purpose,world,&format!("{}:{n}",h.slot))?).map_err(|e|format!("Protected chunk read: {e}"))?.ok_or("Protected chunk absent")?;if b.bytes().len()!=CHUNK.min(h.len-n*CHUNK){return Err("Protected chunk length".into())}bytes.extend_from_slice(b.bytes());}if format!("{:x}",Sha256::digest(&*bytes))!=h.digest{return Err("Protected digest differs".into())}Ok(Some(bytes))}
#[cfg(test)]mod tests{
 use super::*;use std::sync::Mutex;
 #[derive(Default)]struct Store{values:Mutex<std::collections::BTreeMap<String,Vec<u8>>>,fail:Mutex<Option<usize>>}
 impl CredentialStore for Store{fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{let mut n=self.fail.lock().unwrap();if let Some(left)=n.as_mut(){if *left==0{return Err(crate::secrets::StoreError::Unavailable)}*left-=1;}self.values.lock().unwrap().insert(format!("{p:?}"),b.bytes().to_vec());Ok(())}fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.values.lock().unwrap().get(&format!("{p:?}")).map(|b|SecretBlob::new(b.clone())).transpose()}fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.values.lock().unwrap().remove(&format!("{p:?}"));Ok(())}}
 #[test]fn startup_repair_protected_chunk_failure_preserves_exact_original_and_bounds_growth(){
  let s=Scope{origin:"https://chunks.invalid".into(),service:"service".into(),service_epoch:"epoch".into(),account:"account".into(),device:uuid::Uuid::new_v4(),desktop:"desktop".into(),desktop_epoch:"session".into(),room:"room".into(),run:"run".into(),run_epoch:"run-epoch".into(),config:1,config_digest:"a".repeat(64),preparation:"prep".into()};let world=uuid::Uuid::new_v4();let store=Store::default();let first=vec![b'a';MAX];let second=vec![b'b';MAX];save(&store,&s,"pending",world,&first).unwrap();
  for cut in 0..=MAX.div_ceil(CHUNK){*store.fail.lock().unwrap()=Some(cut);assert!(save(&store,&s,"pending",world,&second).is_err());assert_eq!(&*load(&store,&s,"pending",world).unwrap().unwrap(),&first);assert!(store.values.lock().unwrap().len()<=73);}
  *store.fail.lock().unwrap()=None;for _ in 0..20{save(&store,&s,"pending",world,&second).unwrap()}assert_eq!(&*load(&store,&s,"pending",world).unwrap().unwrap(),&second);assert_eq!(store.values.lock().unwrap().len(),73);let mut foreign=s.clone();foreign.account="another".into();assert!(load(&store,&foreign,"pending",world).unwrap().is_none());assert!(save(&store,&s,"pending",world,&vec![0;MAX+1]).is_err());
 }
 #[test]fn lc1_head_write_os_failure_preserves_atomic_previous_record_and_retry(){
  use std::sync::atomic::{AtomicBool,Ordering};struct HeadFailure{store:Store,armed:AtomicBool}
  impl CredentialStore for HeadFailure{fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{if b.bytes().starts_with(b"{\"slot\"")&&self.armed.load(Ordering::Acquire){return Err(crate::secrets::StoreError::Windows{operation:"write",code:8,blob_bytes:b.bytes().len()})}self.store.save(p,b)}fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.store.load(p)}fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.store.delete(p)}}
  let s=Scope{origin:"https://lc1-head.invalid".into(),service:"service".into(),service_epoch:"epoch".into(),account:"account".into(),device:uuid::Uuid::new_v4(),desktop:"desktop".into(),desktop_epoch:"session".into(),room:"room".into(),run:"run".into(),run_epoch:"epoch".into(),config:1,config_digest:"a".repeat(64),preparation:"prep".into()};let world=uuid::Uuid::new_v4();let store=HeadFailure{store:Store::default(),armed:AtomicBool::new(false)};let first=vec![b'a';4910];let next=vec![b'b';4910];save(&store,&s,"lc1-head",world,&first).unwrap();store.armed.store(true,Ordering::Release);let error=save(&store,&s,"lc1-head",world,&next).unwrap_err();assert!(error.contains("Protected commit write")&&error.contains("os=8")&&error.contains("payload_bytes=4910")&&error.contains("chunks=3"));assert_eq!(&*load(&store,&s,"lc1-head",world).unwrap().unwrap(),&first);store.armed.store(false,Ordering::Release);save(&store,&s,"lc1-head",world,&next).unwrap();assert_eq!(&*load(&store,&s,"lc1-head",world).unwrap().unwrap(),&next);assert_eq!(store.store.values.lock().unwrap().len(),7);let mut foreign=s.clone();foreign.account="foreign".into();assert!(load(&store,&foreign,"lc1-head",world).unwrap().is_none());foreign=s.clone();foreign.device=uuid::Uuid::new_v4();assert!(load(&store,&foreign,"lc1-head",world).unwrap().is_none());assert!(load(&store,&s,"lc1-head",uuid::Uuid::new_v4()).unwrap().is_none());
 }
}
